@router.get("/contracts/{contract_id}/revisions")
async def get_contract_revision_history(
    contract_id: PydanticObjectId,
    current_user: User = Depends(get_current_user)
):
    contract = await LegalContract.get(contract_id)
    if not contract:
        raise HTTPException(status_code=404, detail="Contract not found")

    if current_user.organization_id not in contract.party_organization_ids and not current_user.is_legal_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to view contract revisions")

    return {
        "contract_id": str(contract.id),
        "title": contract.title,
        "revisions": [
            {"revision_num": rev.num, "modified_by": rev.author_email, "diff_summary": rev.summary}
            for rev in contract.revisions
        ]
    }
